<script setup lang="ts">
import { computed, ref, watch } from 'vue'
const mode=ref<'dark'|'light'|'auto'>((localStorage.getItem('cyberlife-theme') as 'dark'|'light'|'auto')||'dark');const volume=ref(Number(localStorage.getItem('cyberlife-volume')||70));const playing=ref(false);const page=ref<'now'|'past'|'future'>('now');const playlist=ref<Record<string,string[]>>(JSON.parse(localStorage.getItem('cyberlife-playlists')||'{"now":[],"past":[],"future":[]}'));const selectedPlaylist=computed(()=>playlist.value[page.value]);
watch([mode,volume,playing],()=>{localStorage.setItem('cyberlife-theme',mode.value);localStorage.setItem('cyberlife-volume',String(volume.value));document.documentElement.dataset.theme=mode.value;});function addTrack(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>20*1024*1024){alert('音频不能超过 20MB');return}if(selectedPlaylist.value.length>=50){alert('每页最多 50 首');return}selectedPlaylist.value.push(file.name);localStorage.setItem('cyberlife-playlists',JSON.stringify(playlist.value));(event.target as HTMLInputElement).value=''}function removeTrack(index:number){selectedPlaylist.value.splice(index,1);localStorage.setItem('cyberlife-playlists',JSON.stringify(playlist.value))}
</script>
<template><main class="settings-page"><header><div><p class="eyebrow">SYSTEM / SETTINGS</p><h1>设置</h1></div></header><section class="settings-grid"><article class="panel"><h2>显示模式</h2><div class="segmented"><button v-for="item in [['dark','始终黑色'],['light','始终白色'],['auto','日出日落']]" :key="item[0]" :class="{active:mode===item[0]}" @click="mode=item[0] as typeof mode">{{item[1]}}</button></div><label class="setting-row">全局音量 <input v-model.number="volume" type="range" min="0" max="100"/> {{volume}}%</label><button class="primary" @click="playing=!playing">{{playing?'停止播放':'开始播放'}}</button></article><article class="panel"><h2>页面歌单</h2><div class="segmented"><button v-for="item in ['now','past','future']" :key="item" :class="{active:page===item}" @click="page=item as typeof page">{{item==='now'?'现在':item==='past'?'过去':'未来'}}</button></div><label class="upload-audio">上传音频（MP3/OGG/FLAC/M4A/WAV，20MB）<input type="file" accept="audio/mp3,audio/ogg,audio/flac,audio/mp4,audio/wav" @change="addTrack"/></label><ul class="track-list"><li v-for="(track,index) in selectedPlaylist" :key="track+index"><span>{{track}}</span><button @click="removeTrack(index)">移除</button></li><li v-if="!selectedPlaylist.length" class="empty">当前页面没有上传曲目。</li></ul></article></section></main></template>